excels.excel:

EXPORT WITH SHEET="部门费用统计", HEADER=true,
    MAPPING={"a":"部门","b":"费用类型","c":"金额"},
    FORMAT={"c":"#,##0.00"},
    FORMULAS={C5:'SUM(C2:C4)',C9:'SUM(C6:C8)',C13:'SUM(C10:C12)',C14:'C5+C9+C13'},
    STYLE={
        ROW 5:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right},
        ROW 9:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right},
        ROW 13:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right},
        ROW 14:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right}
    }
